	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func goodNodes(root *TreeNode) int {
	return count(root, -10e4)
}

func count(root *TreeNode, max int) int {
	if root == nil {
		return 0
	}
	result := 0
	if root.Val >= max {
		max = root.Val
		result++
	}

	return result + count(root.Left, max) + count(root.Right, max)
}

